<?php
require_once 'auth_check.php'; require_once 'koneksi.php'; require_once 'csrf.php'; wajib_role(['ADMIN']);
$pesan='';$error='';$edit=null;
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_verify();$aksi=$_POST['aksi']??'';$id=(int)($_POST['id_program_studi']??0);$idF=(int)($_POST['id_fakultas']??0);$kode=trim($_POST['kode_program_studi']??'');$nama=trim($_POST['nama_program_studi']??'');$jenjang=trim($_POST['jenjang']??'');$status=$_POST['status_aktif']??'Aktif';
if($idF<=0||$kode===''||$nama===''||$jenjang==='')$error='Fakultas, kode, nama, dan jenjang wajib diisi.'; elseif($aksi==='tambah'||$aksi==='edit'){
 if($aksi==='tambah'){$st=mysqli_prepare($koneksi,'INSERT INTO program_studi (id_fakultas,kode_program_studi,nama_program_studi,jenjang,status_aktif) VALUES (?,?,?,?,?)');mysqli_stmt_bind_param($st,'issss',$idF,$kode,$nama,$jenjang,$status);}else{$st=mysqli_prepare($koneksi,'UPDATE program_studi SET id_fakultas=?,kode_program_studi=?,nama_program_studi=?,jenjang=?,status_aktif=? WHERE id_program_studi=?');mysqli_stmt_bind_param($st,'issssi',$idF,$kode,$nama,$jenjang,$status,$id);}
 if($st&&mysqli_stmt_execute($st))$pesan=$aksi==='tambah'?'Program Studi berhasil ditambahkan.':'Program Studi berhasil diperbarui.';else$error='Gagal menyimpan Program Studi: '.mysqli_error($koneksi);if($st)mysqli_stmt_close($st);
} elseif($aksi==='hapus'){ $st=mysqli_prepare($koneksi,'DELETE FROM program_studi WHERE id_program_studi=?');mysqli_stmt_bind_param($st,'i',$id);if(mysqli_stmt_execute($st))$pesan='Program Studi berhasil dihapus.';else$error='Program Studi tidak dapat dihapus karena masih digunakan.';mysqli_stmt_close($st);}}
if(isset($_GET['edit'])){$id=(int)$_GET['edit'];$st=mysqli_prepare($koneksi,'SELECT * FROM program_studi WHERE id_program_studi=?');mysqli_stmt_bind_param($st,'i',$id);mysqli_stmt_execute($st);$edit=mysqli_fetch_assoc(mysqli_stmt_get_result($st));mysqli_stmt_close($st);}
$fak=[];$r=mysqli_query($koneksi,'SELECT id_fakultas,nama_fakultas FROM fakultas ORDER BY nama_fakultas');if($r)while($x=mysqli_fetch_assoc($r))$fak[]=$x;
$data=[];$r=mysqli_query($koneksi,'SELECT ps.id_program_studi,ps.kode_program_studi,ps.nama_program_studi,ps.jenjang,ps.status_aktif,f.nama_fakultas FROM program_studi ps INNER JOIN fakultas f ON ps.id_fakultas=f.id_fakultas ORDER BY f.nama_fakultas,ps.nama_program_studi');if($r)while($x=mysqli_fetch_assoc($r))$data[]=$x;
?><!DOCTYPE html><html lang="id"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Program Studi - SIM Mahasiswa</title><link rel="stylesheet" href="style.css"></head><body class="app-body"><?php include 'topbar.php';include 'sideleftbar.php';?><main class="main-content"><div class="page-heading"><div><span class="eyebrow">DATA AKADEMIK</span><h1>Kelola Program Studi</h1><p>Tambah, ubah, dan kelola Program Studi.</p></div></div><?php if($pesan):?><div class="alert alert-success"><?=htmlspecialchars($pesan)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=htmlspecialchars($error)?></div><?php endif;?><section class="dashboard-panel form-panel"><div class="panel-heading"><h2><?=$edit?'Edit Program Studi':'Tambah Program Studi'?></h2></div><form method="post" class="crud-form"><?=csrf_field()?><input type="hidden" name="aksi" value="<?=$edit?'edit':'tambah'?>"><?php if($edit):?><input type="hidden" name="id_program_studi" value="<?=intval($edit['id_program_studi'])?>"><?php endif;?><div class="crud-grid"><div class="form-group"><label>Fakultas</label><select name="id_fakultas" required><option value="">-- Pilih Fakultas --</option><?php foreach($fak as $f):?><option value="<?=intval($f['id_fakultas'])?>" <?=intval($edit['id_fakultas']??0)===intval($f['id_fakultas'])?'selected':''?>><?=htmlspecialchars($f['nama_fakultas'])?></option><?php endforeach;?></select></div><div class="form-group"><label>Kode Program Studi</label><input name="kode_program_studi" required value="<?=htmlspecialchars($edit['kode_program_studi']??'')?>"></div><div class="form-group"><label>Nama Program Studi</label><input name="nama_program_studi" required value="<?=htmlspecialchars($edit['nama_program_studi']??'')?>"></div><div class="form-group"><label>Jenjang</label><select name="jenjang"><option <?=($edit['jenjang']??'S1')==='S1'?'selected':''?>>S1</option><option <?=($edit['jenjang']??'')==='S2'?'selected':''?>>S2</option><option <?=($edit['jenjang']??'')==='S3'?'selected':''?>>S3</option><option <?=($edit['jenjang']??'')==='D3'?'selected':''?>>D3</option><option <?=($edit['jenjang']??'')==='D4'?'selected':''?>>D4</option></select></div><div class="form-group"><label>Status</label><select name="status_aktif"><option value="Aktif" <?=($edit['status_aktif']??'Aktif')==='Aktif'?'selected':''?>>Aktif</option><option value="Nonaktif" <?=($edit['status_aktif']??'')==='Nonaktif'?'selected':''?>>Nonaktif</option></select></div></div><div class="form-actions"><button class="btn btn-primary"><?=$edit?'Simpan Perubahan':'Tambah'?></button><?php if($edit):?><a class="btn btn-outline" href="program_studi.php">Batal</a><?php endif;?></div></form></section><section class="dashboard-panel table-panel"><div class="panel-heading table-heading"><h2>Daftar Program Studi</h2><span class="table-count"><?=count($data)?> program studi</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>KODE</th><th>NAMA</th><th>FAKULTAS</th><th>JENJANG</th><th>STATUS</th><th>AKSI</th></tr></thead><tbody><?php foreach($data as $x):?><tr><td><?=htmlspecialchars($x['kode_program_studi'])?></td><td><?=htmlspecialchars($x['nama_program_studi'])?></td><td><?=htmlspecialchars($x['nama_fakultas'])?></td><td><?=htmlspecialchars($x['jenjang'])?></td><td><?=htmlspecialchars($x['status_aktif'])?></td><td><div class="action-group"><a class="action-edit" href="program_studi.php?edit=<?=intval($x['id_program_studi'])?>">Edit</a><form method="post" class="inline-form" onsubmit="return confirm('Hapus Program Studi ini?')"><?=csrf_field()?><input type="hidden" name="aksi" value="hapus"><input type="hidden" name="id_program_studi" value="<?=intval($x['id_program_studi'])?>"><button class="action-delete">Hapus</button></form></div></td></tr><?php endforeach;if(!$data):?><tr><td colspan="6" class="empty-state">Belum ada Program Studi.</td></tr><?php endif;?></tbody></table></div></section></main><script>function toggleSidebar(){document.getElementById('sidebar').classList.toggle('show');}</script></body></html>
